"""
Validate a brand-lock Markdown file.

REQUIRED_IDENTITY_FIELDS = {
    "brand",
    "one-line description",
    "archetype",
    "voice posture",
}

def parse_headings(text: str) -> list[tuple[int, str]]:
    """Return list of (level, heading_text_lower) for every Markdown heading."""
    out = []
    for line in text.splitlines():
        m = re.match(r"^(#{1,6})\s+(.+?)\s*$", line)
        if m:
            out.append((len(m.group(1)), m.group(2).strip().lower()))
    return out

def extract_section(text: str, heading_lower: str) -> str:
    """Extract the body of a section by its heading. Empty string if not found."""
    lines = text.splitlines()
    in_section = False
    section_lines: list[str] = []
    section_level: int | None = None
    for line in lines:
        m = re.match(r"^(#{1,6})\s+(.+?)\s*$", line)
        if m:
            level = len(m.group(1))
            heading = m.group(2).strip().lower()
            if not in_section:
                if heading == heading_lower:
                    in_section = True
                    section_level = level
                    continue
            else:
                if section_level is not None and level <= section_level:
                    break
        if in_section:
            section_lines.append(line)
    return "\n".join(section_lines)

def check_structure(text: str) -> list[str]:
    errors: list[str] = []
    heading_set = {h for _, h in parse_headings(text)}

if "identity" in heading_set:
    identity_body = extract_section(text, "identity").lower()
    for field in sorted(REQUIRED_IDENTITY_FIELDS):
        if field not in identity_body:
            errors.append(f"identity section missing field: '{field}'")

if "palette" in heading_set:
    palette_body = extract_section(text, "palette")
    if not re.search(r"#[0-9A-Fa-f]{6}|#_{6}", palette_body):
        errors.append(
            "palette section has no hex color values (or template placeholders)"
        )

def check_roles(text: str) -> list[str]:
    """
    The palette role names the HTML preview maps onto CSS variables.

def check_typography(text: str) -> list[str]:
    warnings: list[str] = []
    fonts = parse_typography(text)
    for key, label in (("display_font", "Display"), ("body_font", "Body")):
        if not fonts.get(key):
            warnings.append(
                f"typography declares no {key.replace('_', ' ')} in a readable form; "
                f'expected ``**{label} font:** `Font Name Weight` `` with the name '
                f"backticked immediately after the label"
            )
    return warnings

taken = header["snapshot_taken"]
if not taken:
    errors.append(
        "snapshot is missing its '<!-- snapshot taken: ... -->' header, so nothing "
        "records when this brand state was frozen"
    )
elif ISO_INSTANT_RE.match(taken):
    pass
elif ISO_DATE_RE.match(taken):
    warnings.append(
        f"snapshot taken '{taken}' is a date with no time; a full UTC instant "
        f"(YYYY-MM-DDThh:mm:ssZ) is what makes two runs on one day distinguishable"
    )
else:
    errors.append(
        f"snapshot taken '{taken}' is not ISO-8601; expected YYYY-MM-DDThh:mm:ssZ"
    )

if not header["source"]:
    errors.append(
        "snapshot is missing its '<!-- source: ... -->' header, so nothing records "
        "which brand-pack it was copied from"
    )

def validate_brand_lock(
    path: Path, snapshot: bool = False, require_configured: bool = False
) -> tuple[list[str], list[str]]:
    """Return (errors, warnings). Empty errors means it passes."""
    if not path.exists():
        return ([f"file does not exist: {path}"], [])

unconfigured = is_unconfigured(text)
if unconfigured:
    if require_configured or snapshot:
        errors.append(
            "palette still contains template placeholders (#______), so this is an "
            "unfilled template rather than a real brand-lock"
        )
    else:
        warnings.append(
            "palette contains template placeholders (#______); fine for a template, "
            "not for production work"
        )

with tempfile.TemporaryDirectory() as tmp:
    for i, (label, text, kwargs, should_fail) in enumerate(cases):
        path = Path(tmp) / f"case-{i}.md"
        path.write_text(text, encoding="utf-8")
        errors, _ = validate_brand_lock(path, **kwargs)
        if bool(errors) == should_fail:
            print(f"  ok    selftest: {label}")
        else:
            print(f"  FAIL  selftest: {label} -> {errors or '(no errors)'}")
            ok = False

warn_path = Path(tmp) / "warn.md"
warn_path.write_text(
    minimal.replace("| Muted | `#888888` | captions |", ""), encoding="utf-8"
)
_, warnings = validate_brand_lock(warn_path)
if any("no 'muted' role" in w for w in warnings):
    print("  ok    selftest: a missing palette role warns")
else:
    print(f"  FAIL  selftest: expected a muted-role warning, got {warnings}")
    ok = False

if "--snapshots" in args:
    paths = sorted(REPO_ROOT.rglob("brand-lock.snapshot.md"))
    if not paths:
        print("ERROR: no brand-lock.snapshot.md files found in the repo")
        return 1
else:
    paths = [Path(a) for a in args if not a.startswith("--")]
    if not paths:
        print("ERROR: no brand-lock files given")
        return 2

total_errors = 0
total_warnings = 0
for path in paths:
    errors, warnings = validate_brand_lock(path, snapshot, require_configured)
    try:
        shown = path.relative_to(REPO_ROOT)
    except ValueError:
        shown = path
    total_warnings += len(warnings)
    if not errors:
        print(f"  ok    {shown}")
    else:
        total_errors += len(errors)
        print(f"  FAIL  {shown}")
        for err in errors:
            print(f"        - {err}")
    for warn in warnings:
        print(f"  warn  {shown}: {warn}")

#!/usr/bin/env python3
"""
Validate the generator capability matrix and the adapter prose that defers to it.

try:
    from jsonschema import Draft202012Validator
except ImportError:
    print("ERROR: jsonschema not installed. Run: pip install pyyaml jsonschema")
    sys.exit(1)

def _parse_date(value: str) -> date | None:
    try:
        y, m, d = (int(p) for p in value.split("-"))
        return date(y, m, d)
    except (ValueError, AttributeError):
        return None

def adapter_word_bound(text: str) -> int | None:
    """Highest word count the adapter prose advertises, or None if it names none."""
    bounds: list[int] = []
    for m in WORD_RANGE_RE.finditer(text):
        bounds.append(max(int(m.group(1)), int(m.group(2))))
    if not bounds:
        for m in WORD_SINGLE_RE.finditer(text):
            bounds.append(int(m.group(1)))
    return max(bounds) if bounds else None

bound = adapter_word_bound(text)
if bound is None:
    warnings.append(
        f"prose: '{gid}.md' advertises no word budget, so the matrix value "
        f"({entry['max_prompt_words']}) is the only guidance a reader gets"
    )
elif bound > entry["max_prompt_words"]:
    errors.append(
        f"prose: '{gid}.md' advertises up to {bound} words but the matrix caps "
        f"max_prompt_words at {entry['max_prompt_words']}"
    )

aspect = entry["aspect_param"]
if aspect not in text:
    errors.append(
        f"prose: '{gid}.md' never mentions aspect_param '{aspect}'. The matrix "
        f"wins, so the forge will send a parameter the adapter does not document"
    )

notes = entry.get("notes") or ""
for m in NOTES_WORD_RE.finditer(notes):
    cited = int(m.group(1))
    if cited > entry["max_prompt_words"]:
        warnings.append(
            f"self-consistency: '{gid}' notes cite {cited} words but "
            f"max_prompt_words is {entry['max_prompt_words']}"
        )

if not CAPS.exists():
    return ([f"missing {CAPS.relative_to(REPO_ROOT)}"], warnings)
if not CAPS_SCHEMA.exists():
    return ([f"missing {CAPS_SCHEMA.relative_to(REPO_ROOT)}"], warnings)

caps, caps_err = load_json(CAPS)
if caps_err:
    return ([f"_capabilities.json: {caps_err}"], warnings)
schema, schema_err = load_json(CAPS_SCHEMA)
if schema_err:
    return ([f"capabilities.schema.json: {schema_err}"], warnings)

entries = {g["id"]: g for g in caps["generators"]}
cap_ids = set(entries)
md_ids = {
    p.stem
    for p in ADAPTERS_DIR.glob("*.md")
    if p.stem not in NON_ADAPTER_STEMS
}

# 2. File parity
for missing_md in sorted(cap_ids - md_ids):
    errors.append(
        f"parity: capability id '{missing_md}' has no adapter file {missing_md}.md"
    )
for missing_cap in sorted(md_ids - cap_ids):
    errors.append(
        f"parity: adapter '{missing_cap}.md' has no entry in _capabilities.json"
    )

# 5. Staleness
reviewed = _parse_date(caps.get("matrix_last_reviewed", ""))
if reviewed is None:
    warnings.append("matrix_last_reviewed is not a parseable date")
elif (today - reviewed).days > STALE_AFTER_DAYS:
    warnings.append(
        f"matrix_last_reviewed is {(today - reviewed).days} days old "
        f"(> {STALE_AFTER_DAYS}); re-verify the matrix"
    )
for g in caps["generators"]:
    lv = _parse_date(g.get("last_verified", ""))
    if lv is not None and (today - lv).days > STALE_AFTER_DAYS:
        warnings.append(
            f"'{g['id']}' last_verified is {(today - lv).days} days old "
            f"(> {STALE_AFTER_DAYS}); re-verify this generator"
        )

entry = {"id": "x", "max_prompt_words": 80, "aspect_param": "--ar", "notes": "Over 100 words underperforms."}
_, warnings = check_prose_parity(entry, "Aim for **40-80 words** with `--ar`.")
if any("self-consistency" in w for w in warnings):
    print("  ok    selftest: notes citing more words than the cap are flagged")
else:
    print(f"  FAIL  selftest: expected a self-consistency warning, got {warnings}")
    ok = False

if adapter_word_bound("no budget stated here") is None:
    print("  ok    selftest: prose with no word budget reports none")
else:
    print("  FAIL  selftest: found a word budget where there is none")
    ok = False

def main() -> int:
    if "--selftest" in sys.argv[1:]:
        return selftest()

for w in warnings:
    print(f"  warn  {w}")
if warnings:
    print()

#!/usr/bin/env python3
"""
Validate critique.json files against the critique schema AND the gating invariant.

try:
    from jsonschema import Draft202012Validator
except ImportError:
    print("ERROR: jsonschema not installed. Run: pip install pyyaml jsonschema")
    sys.exit(1)

def _load_schema() -> dict:
    data, err = load_json(SCHEMA_PATH)
    if err:
        raise RuntimeError(err)
    return data

if "blocking" in severities and verdict != "REJECT":
    errors.append(
        f"gating: a 'blocking' issue requires verdict REJECT, got '{verdict}'"
    )
if majors >= MAJOR_REJECT_THRESHOLD and verdict != "REJECT":
    errors.append(
        f"gating: {majors} 'major' issues require verdict REJECT "
        f"(threshold {MAJOR_REJECT_THRESHOLD}), got '{verdict}'"
    )
if majors and verdict == "ACCEPT":
    errors.append(
        "gating: a 'major' issue caps the verdict at REVISE; ACCEPT is not allowed"
    )
return errors

def check_provenance(data: dict, known_generators: set[str]) -> list[str]:
    """The provenance invariant. Only applies from version 1.1."""
    errors: list[str] = []
    if data.get("version") == "1.0":
        return errors

for ref_key, hash_key in REF_HASH_PAIRS:
    ref, digest = data.get(ref_key), data.get(hash_key)
    if ref and not digest:
        errors.append(f"provenance: {ref_key} is set but {hash_key} is null")
    if digest and not ref:
        errors.append(f"provenance: {hash_key} is set but {ref_key} is null")

if not data.get("image_ref"):
    errors.append(
        "provenance: image_ref is null; a verdict that names no image cannot be audited"
    )

if data.get("confidence") == "HIGH":
    missing = [
        key
        for key in ("shot_id", "brand_lock_ref", "prompt_ref")
        if not data.get(key)
    ]
    if missing:
        errors.append(
            "provenance: confidence HIGH requires "
            + ", ".join(missing)
            + " to be identified"
        )

generator = data.get("generator")
if generator and known_generators and generator not in known_generators:
    errors.append(
        f"provenance: generator '{generator}' is not an id in the capability matrix"
    )

for err in sorted(validator.iter_errors(data), key=lambda e: list(e.path)):
    loc = "/".join(str(p) for p in err.path) or "(root)"
    errors.append(f"schema: {loc}: {err.message}")
if errors:
    return (errors, warnings)  # the gates assume a schema-valid shape

if data.get("version") == "1.0":
    warnings.append(
        "version 1.0 carries no run id, no round, and no content hashes, so the "
        "verdict cannot be tied to the bytes it reviewed; re-emit as 1.1"
    )

def validate_path(
    path: Path,
    validator: Draft202012Validator,
    known_generators: set[str] | None = None,
) -> tuple[list[str], list[str]]:
    data, err = load_json(path)
    if err:
        return ([err], [])
    if not isinstance(data, dict):
        return ([f"top level is not an object: {path}"], [])
    return validate_doc(data, validator, known_generators)

def doc(**overrides) -> dict:
    out = {
        "version": "1.1",
        **base_provenance,
        "verdict": "REVISE",
        "confidence": "HIGH",
        "issues": [dict(major_issue)],
    }
    out.update(overrides)
    return out

def selftest() -> int:
    validator = Draft202012Validator(_load_schema())
    known = capability_ids() or {"flux"}
    ok = True

for label, document, should_pass in _selftest_cases():
    errors, _ = validate_doc(document, validator, known)
    passed = not errors
    if passed == should_pass:
        print(f"  ok    selftest: {label}")
    else:
        detail = errors if errors else ["(no errors raised)"]
        print(f"  FAIL  selftest: {label} -> {detail}")
        ok = False

def _collect(args: list[str]) -> list[Path] | None:
    if "--examples" in args:
        found = sorted(EXAMPLES_DIR.glob("*.json"))
        found += critique_paths(EXAMPLES_DIR / "worked-run")
        return found or None

paths: list[Path] = []
for raw in args:
    path = Path(raw)
    if path.is_dir():
        found = critique_paths(path)
        if not found:
            print(f"  FAIL  {raw}")
            print("        - no critique files found in this output tree")
            return None
        paths.extend(found)
    else:
        paths.append(path)
return paths

def main() -> int:
    args = sys.argv[1:]
    if not args:
        print("Usage: python tools/validate_critique.py <critique.json|output-dir> [...]")
        print("       python tools/validate_critique.py --examples")
        print("       python tools/validate_critique.py --selftest")
        return 2
    if "--selftest" in args:
        return selftest()

if not SCHEMA_PATH.exists():
    print(f"ERROR: schema not found at {SCHEMA_PATH}")
    return 1

paths = _collect(args)
if paths is None:
    return 1

total_errors = 0
total_warnings = 0
for path in paths:
    errors, warnings = validate_path(path, validator, known)
    try:
        label = path.relative_to(REPO_ROOT)
    except ValueError:
        label = path
    total_warnings += len(warnings)
    if not errors:
        print(f"  ok    {label}")
    else:
        total_errors += len(errors)
        print(f"  FAIL  {label}")
        for err in errors:
            print(f"        - {err}")
    for warn in warnings:
        print(f"  warn  {label}: {warn}")

#!/usr/bin/env python3
"""
Validate the prompt files visual-prompt-forge writes.

def parse_blocks(text: str) -> tuple[dict[str, str], list[tuple[str, str]]]:
    """Return (header fields, [(shot_id, prompt body)])."""
    header: dict[str, str] = {}
    blocks: list[tuple[str, list[str]]] = []
    current: list[str] | None = None

for line in text.splitlines():
    m = SHOT_HEADER.match(line)
    if m:
        current = []
        blocks.append((m.group(1), current))
        continue
    if current is None:
        hm = re.match(r"^#\s*([A-Za-z-]+)\s*:\s*(.+?)\s*$", line)
        if hm:
            header[hm.group(1).strip()] = hm.group(2).strip()
        continue
    if not COMMENT.match(line):
        current.append(line)

def check_file(
    path: Path, shots_data: dict, caps: dict[str, dict]
) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings: list[str] = []
    label = path.name

for field in HEADER_FIELDS:
    if field not in header:
        warnings.append(f"{label}: header is missing '# {field}:'")

generator = header.get("Generator", "").split()[0] if header.get("Generator") else None
entry = caps.get(generator) if generator else None
if generator and entry is None:
    errors.append(
        f"{label}: header names generator '{generator}', which is not an id in "
        f"_capabilities.json"
    )
if generator is None:
    # Fall back to the filename: flux.txt or revised-flux.txt
    stem = path.stem.replace("revised-", "")
    entry = caps.get(stem)
    if entry:
        warnings.append(
            f"{label}: no '# Generator:' header, inferred '{stem}' from the filename"
        )

project = shots_data.get("project", {})
if "Aspect" in header and header["Aspect"] != project.get("aspect"):
    errors.append(
        f"{label}: header aspect '{header['Aspect']}' does not match "
        f"project.aspect '{project.get('aspect')}'"
    )

shot_ids = [s["id"] for s in shots_data.get("shots", [])]
by_id = {s["id"]: s for s in shots_data.get("shots", [])}
series = shots_data.get("series_lock", {})

seen: set[str] = set()
for sid, body in blocks:
    if sid in seen:
        errors.append(f"{label}: {sid} appears in more than one block")
    seen.add(sid)
    if sid not in by_id:
        errors.append(f"{label}: names {sid}, which is not in shots.json")
        continue
    if not body:
        errors.append(f"{label}: {sid} has a header but no prompt body")
        continue

if entry:
    words = len(body.split())
    ceiling = entry["max_prompt_words"]
    if words > ceiling:
        errors.append(
            f"{label}: {sid} is {words} words, over the "
            f"{entry['id']} ceiling of {ceiling}"
        )

low = body.lower()
for key in UNIVERSAL_ANCHORS:
    value = series.get(key)
    if value and value.lower() not in low:
        errors.append(
            f"{label}: {sid} does not carry the series_lock {key} verbatim. "
            f"Paraphrasing an anchor is what makes shots stop matching each other"
        )
character = series.get("character")
if character and character.lower() not in low:
    warnings.append(
        f"{label}: {sid} does not carry the series_lock character verbatim; "
        f"correct only if this shot has no person in it"
    )

# Rule 1: text is composited, never described.
overlays_path = path.parent.parent.parent / "text-overlays.json"
overlays_data, ov_err = load_json(overlays_path)
if not ov_err and isinstance(overlays_data, dict):
    for overlay in overlays_data.get("overlays", []):
        content = overlay.get("content")
        if not isinstance(content, str) or len(content) < 8:
            continue
        needle = content.lower().rstrip(".!?")
        for sid, body in blocks:
            if needle in body.lower():
                errors.append(
                    f"{label}: {sid} contains the copy of overlay "
                    f"{overlay.get('id')} verbatim. On-screen text is composited, "
                    f"never put in an image prompt"
                )

is_revision = path.name.startswith("revised-")
if not is_revision:
    for missing in [s for s in shot_ids if s not in seen]:
        errors.append(f"{label}: full pass is missing a block for {missing}")

def collect_prompt_files(target: Path) -> tuple[Path | None, list[Path]]:
    """Return (output_dir, prompt files). Accepts an output dir or a single file."""
    if target.is_file():
        # prompts/round-N/<file>.txt  ->  output dir is three levels up
        return (target.parent.parent.parent, [target])
    if target.is_dir():
        found = sorted(target.glob("prompts/round-*/*.txt"))
        if not found:
            found = sorted(target.glob("prompts/*.txt"))  # pre-3.0.0 flat layout
        return (target, found)
    return (None, [])

def validate_target(target: Path) -> tuple[list[str], list[str]]:
    out_dir, files = collect_prompt_files(target)
    if out_dir is None:
        return ([f"not a file or directory: {target}"], [])
    if not files:
        return ([f"no prompt files found under {target}"], [])

shots_data, err = load_json(out_dir / "shots.json")
if err:
    return ([f"cannot read shots.json next to the prompts: {err}"], [])

SHOTS_FIXTURE = {
    "project": {"aspect": "9:16"},
    "series_lock": {
        "character": "founder in a navy crewneck",
        "environment": "minimalist home office, oak desk",
        "lighting": "soft window light from camera-left",
        "color_grade": "warm filmic with muted teal shadows",
    },
    "shots": [{"id": "shot_01"}, {"id": "shot_02"}],
}

# Rule 1: overlay copy leaking into a prompt.
(out / "text-overlays.json").write_text(
    json.dumps(
        {
            "version": "1.0",
            "overlays": [
                {"id": "text_01", "content": "You are the bottleneck."}
            ],
        }
    )
)
p = out / "prompts" / "round-1" / "flux.txt"
p.write_text(_fixture(good + " The words You are the bottleneck appear.", good))
errors, _ = check_file(p, SHOTS_FIXTURE, caps)
if any("composited" in e for e in errors):
    print("  ok    selftest: overlay copy inside a prompt is caught")
else:
    print(f"  FAIL  selftest: overlay leak not caught -> {errors}")
    ok = False

def main() -> int:
    args = sys.argv[1:]
    if not args:
        print("Usage: python tools/validate_prompts.py <output-dir|prompt-file> [...]")
        print("       python tools/validate_prompts.py --examples")
        print("       python tools/validate_prompts.py --selftest")
        return 2
    if "--selftest" in args:
        return selftest()

total_errors = 0
total_warnings = 0
for target in targets:
    errors, warnings = validate_target(target)
    try:
        shown = target.relative_to(REPO_ROOT)
    except ValueError:
        shown = target
    total_warnings += len(warnings)
    if not errors:
        print(f"  ok    {shown}")
    else:
        total_errors += len(errors)
        print(f"  FAIL  {shown}")
        for e in errors:
            print(f"        - {e}")
    for w in warnings:
        print(f"  warn  {shown}: {w}")

#!/usr/bin/env python3
"""
Validate the provenance chain of a shotkit output tree.

try:
    from jsonschema import Draft202012Validator
except ImportError:
    print("ERROR: jsonschema not installed. Run: pip install pyyaml jsonschema")
    sys.exit(1)

class Report:
    def __init__(self, output_dir: Path) -> None:
        self.output_dir = output_dir
        self.errors: list[str] = []
        self.warnings: list[str] = []
        self.shots: dict[str, dict] = {}
        self.rounds_seen: list[int] = []
        # (path, recorded, actual) -> the labels that referenced it. One edited file is
        # one problem, even when twenty critiques all hash it.
        self.hash_failures: dict[tuple[str, str, str], list[str]] = {}

def as_dict(self) -> dict:
    return {
        "output_dir": str(self.output_dir),
        "ok": not self.errors,
        "errors": self.errors,
        "warnings": self.warnings,
        "rounds": self.rounds_seen,
        "shots": self.shots,
    }

def _check_hash(
    report: Report, label: str, rel: str | None, expected: str | None
) -> None:
    """Compare a recorded hash against the file currently on disk."""
    if not rel or not expected:
        return
    path = report.output_dir / rel
    if not path.exists():
        report.errors.append(f"{label}: '{rel}' is referenced but missing on disk")
        return
    actual = sha256_file(path)
    if actual == expected:
        return
    report.hash_failures.setdefault((rel, expected, actual), []).append(label)

def _finalize_hash_failures(report: Report) -> None:
    """Turn collected hash mismatches into one error per distinct mismatch."""
    for (rel, expected, actual), labels in report.hash_failures.items():
        # Print both hashes in full. Truncating them meant a single mistyped character
        # at the end produced a message showing two identical-looking strings and
        # asserting they differed, which is the least useful moment to be imprecise: a
        # hand-authored run.json is exactly where typos come from.
        detail = (
            f"'{rel}' does not match the hash recorded for it\n"
            f"          recorded: {expected}\n"
            f"          on disk:  {actual}"
        )
        if len(expected) != 64:
            detail += (
                f"\n          the recorded value is {len(expected)} characters, not 64, "
                f"so it is malformed rather than stale"
            )
        elif sum(a != b for a, b in zip(expected, actual)) <= 2:
            detail += (
                "\n          they differ in one or two characters, which usually means "
                "a typo in the recorded hash rather than a changed file"
            )
        if len(labels) == 1:
            detail += f"\n          referenced by: {labels[0]}"
        else:
            shown = ", ".join(labels[:3])
            more = f", and {len(labels) - 3} more" if len(labels) > 3 else ""
            detail += (
                f"\n          referenced by {len(labels)} places: {shown}{more}"
            )
        report.errors.append(detail)

validator = Draft202012Validator(schema)
for e in sorted(validator.iter_errors(run_doc), key=lambda x: list(x.path)):
    loc = "/".join(str(p) for p in e.path) or "(root)"
    report.errors.append(f"run.json schema: {loc}: {e.message}")
if report.errors:
    return None

if run_doc["inputs"].get("brand_lock_configured") is False:
    report.warnings.append(
        "run.json: brand_lock_configured is false, so this run was built against "
        "an unfilled template rather than a real brand-lock"
    )

numbers = [r["round"] for r in run_doc.get("rounds", [])]
report.rounds_seen = sorted(numbers)
if len(numbers) != len(set(numbers)):
    report.errors.append("run.json: duplicate round numbers")
if numbers and sorted(numbers) != list(range(1, max(numbers) + 1)):
    report.errors.append(
        f"run.json: rounds must run 1..N with no gaps, got {sorted(numbers)}"
    )

for rnd in run_doc.get("rounds", []):
    for prompt in rnd.get("prompts", []):
        _check_hash(
            report,
            f"round {rnd['round']} prompt",
            prompt.get("ref"),
            prompt.get("sha256"),
        )
    for shot_id in rnd.get("post_only_shots", []) or []:
        report.warnings.append(
            f"round {rnd['round']}: {shot_id} is recorded as post-only, so it owes "
            f"compositing work that no prompt or frame will show"
        )

def _round_of(path: Path, output_dir: Path, data: dict) -> int:
    """
    Which round a critique belongs to.

The directory name wins, because that is the addressing scheme. A legacy critique
sitting at the output root has no directory to read, so fall back to its own
`round` field and then to 1.
"""
try:
    parent = path.relative_to(output_dir).parent.name
except ValueError:
    parent = ""
if parent.startswith("round-") and parent[len("round-"):].isdigit():
    return int(parent[len("round-"):])
declared = data.get("round")
return declared if isinstance(declared, int) and declared >= 1 else 1

def check_critiques(report: Report, run_doc: dict | None) -> None:
    critique_validator = Draft202012Validator(_load_critique_schema())
    seen: dict[tuple[str, int], Path] = {}

# critique_paths() is the one definition of "where critiques live", shared with
# validate_critique.py and shots-to-html.py. Walking the round directories directly
# meant this tool ignored a legacy root critique.json that the other two read, so
# the preview showed a verdict badge for a shot this tool called unreviewed.
for path in critique_paths(report.output_dir):
    try:
        rel = path.relative_to(report.output_dir)
    except ValueError:
        rel = path
    data, err = load_json(path)
    if err:
        report.errors.append(f"{rel}: {err}")
        continue
    if not isinstance(data, dict):
        report.errors.append(f"{rel}: top level is not an object")
        continue

if in_round_dir and data.get("round") not in (None, round_no):
    report.errors.append(
        f"{rel}: declares round {data.get('round')} but sits in round-{round_no}/"
    )
if run_doc and data.get("run_id") not in (None, run_doc["run_id"]):
    report.errors.append(
        f"{rel}: run_id '{data.get('run_id')}' does not match run.json "
        f"'{run_doc['run_id']}'"
    )

shot_id = data.get("shot_id")
if shot_id:
    key = (shot_id, round_no)
    if key in seen:
        report.errors.append(
            f"{rel}: a second critique for {shot_id} in round {round_no} "
            f"already exists at {seen[key]}; "
            f"two operators reviewed the same shot in the same round"
        )
    else:
        seen[key] = rel

if shot_id:
    entry = report.shots.setdefault(shot_id, {"rounds": {}})
    entry["rounds"][str(round_no)] = {
        "verdict": data.get("verdict"),
        "confidence": data.get("confidence"),
        "critique_ref": str(rel),
        "issues": len(data.get("issues", [])),
    }

def check_coverage(report: Report, run_doc: dict | None) -> None:
    shots_rel = "shots.json"
    if run_doc:
        shots_rel = run_doc["inputs"].get("shots_ref", "shots.json")
    shots_data, err = load_json(report.output_dir / shots_rel)
    shot_ids: list[str] = []
    if err:
        report.warnings.append(f"coverage: cannot read {shots_rel}, skipped ({err})")
    elif isinstance(shots_data, dict):
        shot_ids = [
            s["id"] for s in shots_data.get("shots", []) if isinstance(s.get("id"), str)
        ]

reviewed_by_round: dict[int, set[str]] = {}
for shot_id, entry in report.shots.items():
    for rnd in entry["rounds"]:
        reviewed_by_round.setdefault(int(rnd), set()).add(shot_id)

for round_no, directory in round_dirs(report.output_dir, "frames"):
    reviewed = reviewed_by_round.get(round_no, set())
    for path in sorted(directory.iterdir()):
        if path.suffix.lstrip(".").lower() not in IMAGE_EXTS:
            continue
        frame_shot = path.stem
        if frame_shot not in reviewed:
            report.errors.append(
                f"coverage: frames/round-{round_no}/{path.name} has no critique for "
                f"round {round_no}; it was never reviewed"
            )

for shot_id in shot_ids:
    entry = report.shots.get(shot_id)
    if not entry:
        report.warnings.append(
            f"coverage: {shot_id} has no critique in any round"
        )
        continue
    latest = max(int(r) for r in entry["rounds"])
    entry["latest_round"] = latest
    entry["latest_verdict"] = entry["rounds"][str(latest)]["verdict"]

for shot_id in report.shots:
    if shot_ids and shot_id not in shot_ids:
        report.errors.append(
            f"coverage: a critique names {shot_id}, which is not in {shots_rel}"
        )

def outstanding(report: Report) -> list[str]:
    """Shots whose latest verdict is not ACCEPT."""
    return sorted(
        shot_id
        for shot_id, entry in report.shots.items()
        if entry.get("latest_verdict") not in (None, "ACCEPT")
    )

clean = validate_tree(WORKED_RUN)
if clean.errors:
    print(f"  FAIL  selftest: the bundled worked run should be clean, got: {clean.errors}")
    ok = False
else:
    print("  ok    selftest: the bundled worked run passes")

if outstanding(clean):
    print(f"  FAIL  selftest: worked run should have no outstanding shots, got {outstanding(clean)}")
    ok = False
else:
    print("  ok    selftest: every shot in the worked run ends on ACCEPT")

def main() -> int:
    args = sys.argv[1:]
    if not args:
        print("Usage: python tools/validate_provenance.py <output-dir> [...]")
        print("       python tools/validate_provenance.py <output-dir> --require-accept")
        print("       python tools/validate_provenance.py --examples")
        print("       python tools/validate_provenance.py --selftest")
        return 2
    if "--selftest" in args:
        return selftest()

if "--examples" in args:
    targets = [WORKED_RUN]
elif targets_raw:
    targets = [Path(t) for t in targets_raw]
else:
    print("ERROR: no output directory given")
    return 2

if as_json:
    print(json.dumps([r.as_dict() for r in reports], indent=2))
else:
    print(f"Validating provenance for {len(reports)} output tree(s)")
    print()
    for report in reports:
        try:
            label = report.output_dir.relative_to(REPO_ROOT)
        except ValueError:
            label = report.output_dir
        if report.errors:
            print(f"  FAIL  {label}")
            for err in report.errors:
                print(f"        - {err}")
        else:
            print(f"  ok    {label}  ({len(report.shots)} shot(s), rounds {report.rounds_seen or 'none'})")
        for warn in report.warnings:
            print(f"  warn  {label}: {warn}")
        for shot_id in sorted(report.shots):
            entry = report.shots[shot_id]
            verdict = entry.get("latest_verdict", "?")
            print(
                f"        {shot_id}: {verdict} "
                f"(round {entry.get('latest_round', '?')})"
            )
    print()

failed = any(r.errors for r in reports)
unresolved = {
    str(r.output_dir): outstanding(r) for r in reports if outstanding(r)
}

if not as_json:
    if failed:
        total = sum(len(r.errors) for r in reports)
        print(f"FAILED: {total} provenance error(s).")
    elif require_accept and unresolved:
        for path, shots in unresolved.items():
            print(f"NOT DONE: {path} still has non-ACCEPT shots: {', '.join(shots)}")
    else:
        print("Provenance chain intact.")

if failed:
    return 1
if require_accept and unresolved:
    return 1
return 0

#!/usr/bin/env python3
"""
Validate that every *.schema.json file in the repo is itself valid JSON Schema.

try:
    from jsonschema import Draft202012Validator
    from jsonschema.exceptions import SchemaError
except ImportError:
    print("ERROR: jsonschema not installed. Run: pip install jsonschema")
    sys.exit(1)

def find_schema_files() -> list[Path]:
    """Find every *.schema.json file in the repo."""
    return sorted(REPO_ROOT.rglob("*.schema.json"))

def validate_schema_file(path: Path) -> list[str]:
    """Return a list of errors. Empty list = passes."""
    errors: list[str] = []
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        errors.append(f"invalid JSON: {e}")
        return errors

try:
    Draft202012Validator.check_schema(data)
except SchemaError as e:
    errors.append(f"invalid schema: {e.message}")

if "$id" not in data:
    errors.append("missing '$id' field")
if "title" not in data:
    errors.append("missing 'title' field")
if "description" not in data:
    errors.append("missing 'description' field")

def main() -> int:
    schemas = find_schema_files()
    if not schemas:
        print("ERROR: no *.schema.json files found in repo")
        return 1

total_errors = 0
for path in schemas:
    rel = path.relative_to(REPO_ROOT)
    errors = validate_schema_file(path)
    if not errors:
        print(f"  ok    {rel}")
    else:
        total_errors += len(errors)
        print(f"  FAIL  {rel}")
        for err in errors:
            print(f"        - {err}")

#!/usr/bin/env python3
"""
Validate a storyboard output set: shots.json and text-overlays.json, as instances.

try:
    from jsonschema import Draft202012Validator
except ImportError:
    print("ERROR: jsonschema not installed. Run: pip install pyyaml jsonschema")
    sys.exit(1)

def _schema_errors(data, validator: Draft202012Validator, label: str) -> list[str]:
    out = []
    for err in sorted(validator.iter_errors(data), key=lambda e: list(e.path)):
        loc = "/".join(str(p) for p in err.path) or "(root)"
        out.append(f"{label} schema: {loc}: {err.message}")
    return out

def check_timing(shots: list[dict], duration_s: float) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings: list[str] = []

seen: set[str] = set()
for shot in shots:
    sid = shot.get("id", "?")
    if sid in seen:
        errors.append(f"timing: duplicate shot id '{sid}'")
    seen.add(sid)
    start, end = shot.get("start"), shot.get("end")
    if isinstance(start, (int, float)) and isinstance(end, (int, float)):
        if end <= start:
            errors.append(
                f"timing: {sid} has end ({end}) not after start ({start})"
            )

timed = [
    s
    for s in shots
    if isinstance(s.get("start"), (int, float))
    and isinstance(s.get("end"), (int, float))
]
if not timed:
    return errors, warnings

ordered = sorted(timed, key=lambda s: (s["start"], s["end"]))
for a, b in zip(ordered, ordered[1:]):
    if b["start"] > a["end"] + 1e-9:
        errors.append(
            f"timing: gap between {a['id']} (ends {a['end']}) and "
            f"{b['id']} (starts {b['start']})"
        )
    elif b["start"] < a["end"] - 1e-9:
        errors.append(
            f"timing: overlap between {a['id']} (ends {a['end']}) and "
            f"{b['id']} (starts {b['start']})"
        )

span = max(s["end"] for s in timed) - min(s["start"] for s in timed)
if abs(span - duration_s) > TIMING_TOLERANCE_S:
    errors.append(
        f"timing: covered span {span:g}s does not match project.duration_s "
        f"{duration_s:g}s (tolerance {TIMING_TOLERANCE_S}s)"
    )

if [s["id"] for s in timed] != [s["id"] for s in ordered]:
    warnings.append(
        "timing: shot ids are not in chronological order; readers assume they are"
    )

def check_version_features(shots: list[dict], version: str) -> list[str]:
    """Features may not be used below the version that introduced them."""
    errors: list[str] = []
    if version in ("1.0", "1.1"):
        for shot in shots:
            if isinstance(shot.get("on_screen_text"), list):
                errors.append(
                    f"version: {shot.get('id')} uses the array form of on_screen_text, "
                    f"which requires version 1.2 (file declares {version})"
                )
    if version == "1.0":
        for shot in shots:
            if shot.get("assets") is not None:
                errors.append(
                    f"version: {shot.get('id')} carries an assets block, which "
                    f"requires version 1.1 or later (file declares 1.0)"
                )
    return errors

def check_references(
    shots: list[dict], overlays: list[dict]
) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings: list[str] = []

shot_ids = {s.get("id") for s in shots}
overlay_ids: set[str] = set()
for overlay in overlays:
    oid = overlay.get("id")
    if oid in overlay_ids:
        errors.append(f"reference: duplicate overlay id '{oid}'")
    overlay_ids.add(oid)

referenced: set[str] = set()
for shot in shots:
    for oid in as_overlay_ids(shot.get("on_screen_text")):
        referenced.add(oid)
        if oid not in overlay_ids:
            errors.append(
                f"reference: {shot.get('id')}.on_screen_text '{oid}' has no "
                f"entry in text-overlays.json"
            )

for overlay in overlays:
    oid = overlay.get("id")
    for sid in as_shot_ids(overlay.get("shot_id")):
        if sid not in shot_ids:
            errors.append(
                f"reference: overlay {oid}.shot_id '{sid}' has no entry in shots.json"
            )
    if oid not in referenced:
        errors.append(
            f"reference: overlay {oid} is not reachable from any "
            f"shot.on_screen_text, so no renderer will show it"
        )

def check_overlay_windows(shots: list[dict], overlays: list[dict]) -> list[str]:
    errors: list[str] = []
    by_id = {
        s["id"]: s
        for s in shots
        if isinstance(s.get("start"), (int, float))
        and isinstance(s.get("end"), (int, float))
    }

for overlay in overlays:
    oid = overlay.get("id")
    enter = (overlay.get("enter") or {}).get("at")
    exit_at = (overlay.get("exit") or {}).get("at")
    if not isinstance(enter, (int, float)) or not isinstance(exit_at, (int, float)):
        continue
    if exit_at <= enter:
        errors.append(
            f"overlay: {oid} exit ({exit_at}) is not after enter ({enter})"
        )
    windows = [by_id[s] for s in as_shot_ids(overlay.get("shot_id")) if s in by_id]
    if not windows:
        continue
    lo = min(w["start"] for w in windows)
    hi = max(w["end"] for w in windows)
    if enter < lo - 1e-9 or exit_at > hi + 1e-9:
        errors.append(
            f"overlay: {oid} timing {enter}-{exit_at}s falls outside its shot "
            f"window {lo:g}-{hi:g}s"
        )

def check_brand_alignment(
    shots: list[dict], overlays: list[dict], brand_lock_text: str | None
) -> tuple[list[str], list[str]]:
    errors: list[str] = []
    warnings: list[str] = []

if brand_lock_text is None:
    warnings.append(
        "brand: brand_lock_ref did not resolve, so palette and font checks were skipped"
    )
    return errors, warnings

allowed = palette_hexes(brand_lock_text)
for overlay in overlays:
    color = overlay.get("color")
    if isinstance(color, str) and color.lower() not in allowed:
        errors.append(
            f"brand: overlay {overlay.get('id')} color {color} is not in the "
            f"brand-lock palette"
        )

fonts = {v.lower() for v in parse_typography(brand_lock_text).values() if v}
if fonts:
    for overlay in overlays:
        font = overlay.get("font")
        if isinstance(font, str) and font.lower() not in fonts:
            warnings.append(
                f"brand: overlay {overlay.get('id')} font '{font}' is not a font "
                f"declared in the brand-lock typography section"
            )

for shot in shots:
    subject = shot.get("subject")
    if not isinstance(subject, str):
        continue
    for hex_val in HEX_RE.findall(subject):
        warnings.append(
            f"brand: {shot.get('id')}.subject names a raw hex ({hex_val}); "
            f"colors belong in series_lock and the brand-lock"
        )

def check_text_leak(shots: list[dict], overlays: list[dict]) -> list[str]:
    """On-screen copy repeated inside a shot subject. Text is a separate layer."""
    warnings: list[str] = []
    contents = {
        o.get("id"): o.get("content")
        for o in overlays
        if isinstance(o.get("content"), str) and len(o.get("content", "")) >= 8
    }
    for shot in shots:
        subject = shot.get("subject")
        if not isinstance(subject, str):
            continue
        lowered = subject.lower()
        for oid in as_overlay_ids(shot.get("on_screen_text")):
            content = contents.get(oid)
            if content and content.lower().rstrip(".!?") in lowered:
                warnings.append(
                    f"text: {shot.get('id')}.subject repeats overlay {oid} copy "
                    f"verbatim; on-screen text is composited, never described"
                )
    return warnings

def check_assets(shots: list[dict], known_generators: set[str]) -> list[str]:
    errors: list[str] = []
    if not known_generators:
        return errors
    for shot in shots:
        for entry in (shot.get("assets") or {}).get("generated", []) or []:
            gen = entry.get("generator")
            if isinstance(gen, str) and gen not in known_generators:
                errors.append(
                    f"assets: {shot.get('id')} generated frame names generator "
                    f"'{gen}', which is not in the capability matrix"
                )
            if entry.get("accepted") is True and not entry.get("critique_ref"):
                errors.append(
                    f"assets: {shot.get('id')} has an accepted frame with no "
                    f"critique_ref, which is an unsourced approval"
                )
    return errors

shots_data, err = load_json(shots_path)
if err:
    return ([err], warnings)
if not isinstance(shots_data, dict):
    return ([f"{shots_path}: top level is not an object"], warnings)

shots_schema, s_err = load_json(SHOTS_SCHEMA)
overlays_schema, o_err = load_json(OVERLAYS_SCHEMA)
if s_err or o_err:
    return ([s_err or o_err], warnings)

errors += _schema_errors(
    shots_data, Draft202012Validator(shots_schema), "shots.json"
)

base = shots_path.parent
overlays_path = base / "text-overlays.json"
overlays: list[dict] = []
if overlays_path.exists():
    overlays_data, ov_err = load_json(overlays_path)
    if ov_err:
        errors.append(f"text-overlays.json: {ov_err}")
    else:
        errors += _schema_errors(
            overlays_data,
            Draft202012Validator(overlays_schema),
            "text-overlays.json",
        )
        overlays = overlays_data.get("overlays", []) or []
else:
    for shot in shots_data.get("shots", []) or []:
        if as_overlay_ids(shot.get("on_screen_text")):
            errors.append(
                "reference: shots.json references on-screen text but "
                "text-overlays.json is missing"
            )
            break

if errors:
    # Structure-dependent checks assume schema-valid input.
    return (errors, warnings)

brand_ref = shots_data.get("brand_lock_ref")
brand_text: str | None = None
if isinstance(brand_ref, str):
    brand_path = base / brand_ref
    if brand_path.exists():
        brand_text = brand_path.read_text(encoding="utf-8")
    else:
        errors.append(
            f"brand: brand_lock_ref '{brand_ref}' does not resolve from {base}"
        )
b_err, b_warn = check_brand_alignment(shots, overlays, brand_text)
errors += b_err
warnings += b_warn

def _resolve_target(raw: str) -> Path | None:
    path = Path(raw)
    if path.is_dir():
        candidate = path / "shots.json"
        return candidate if candidate.exists() else None
    return path if path.exists() else None

def selftest() -> int:
    """Prove the cross-field checks fire. Fixtures are in-memory, no files touched."""
    ok = True
    cases = [
        (
            "end not after start",
            lambda: check_timing(
                [{"id": "shot_01", "start": 5.0, "end": 3.0}], 30.0
            )[0],
        ),
        (
            "gap between shots",
            lambda: check_timing(
                [
                    {"id": "shot_01", "start": 0.0, "end": 2.0},
                    {"id": "shot_02", "start": 4.0, "end": 30.0},
                ],
                30.0,
            )[0],
        ),
        (
            "overlap between shots",
            lambda: check_timing(
                [
                    {"id": "shot_01", "start": 0.0, "end": 5.0},
                    {"id": "shot_02", "start": 3.0, "end": 30.0},
                ],
                30.0,
            )[0],
        ),
        (
            "span disagrees with duration",
            lambda: check_timing(
                [{"id": "shot_01", "start": 0.0, "end": 10.0}], 30.0
            )[0],
        ),
        (
            "dangling on_screen_text",
            lambda: check_references(
                [{"id": "shot_01", "on_screen_text": "text_09"}], []
            )[0],
        ),
        (
            "unreachable overlay",
            lambda: check_references(
                [{"id": "shot_01", "on_screen_text": None}],
                [{"id": "text_01", "shot_id": "shot_01"}],
            )[0],
        ),
        (
            "overlay outside its shot window",
            lambda: check_overlay_windows(
                [{"id": "shot_01", "start": 0.0, "end": 2.0}],
                [
                    {
                        "id": "text_01",
                        "shot_id": "shot_01",
                        "enter": {"at": 0.0},
                        "exit": {"at": 9.0},
                    }
                ],
            ),
        ),
        (
            "off-palette overlay color",
            lambda: check_brand_alignment(
                [],
                [{"id": "text_01", "color": "#ABCDEF"}],
                "## Palette\n\n| Role | Hex |\n|---|---|\n| Ink | `#2A2A32` |\n",
            )[0],
        ),
        (
            "accepted frame with no critique_ref",
            lambda: check_assets(
                [
                    {
                        "id": "shot_01",
                        "assets": {"generated": [{"path": "a.png", "accepted": True}]},
                    }
                ],
                {"flux"},
            ),
        ),
        (
            "unknown generator id",
            lambda: check_assets(
                [
                    {
                        "id": "shot_01",
                        "assets": {
                            "generated": [{"path": "a.png", "generator": "runway-sora"}]
                        },
                    }
                ],
                {"flux"},
            ),
        ),
        (
            "1.2 feature used in a 1.0 file",
            lambda: check_version_features(
                [{"id": "shot_01", "on_screen_text": ["text_01", "text_02"]}], "1.0"
            ),
        ),
    ]

for label, fn in cases:
    produced = fn()
    if produced:
        print(f"  ok    selftest: {label} is caught")
    else:
        print(f"  FAIL  selftest: {label} was not caught")
        ok = False

clean, clean_warn = check_timing(
    [
        {"id": "shot_01", "start": 0.0, "end": 2.0},
        {"id": "shot_02", "start": 2.0, "end": 30.0},
    ],
    30.0,
)
if clean or clean_warn:
    print(f"  FAIL  selftest: a clean shot list should pass, got: {clean + clean_warn}")
    ok = False
else:
    print("  ok    selftest: a clean shot list passes")

if "--examples" in args:
    targets = sorted(EXAMPLES_DIR.glob("*/shots.json"))
    if not targets:
        print(f"ERROR: no bundled examples found under {EXAMPLES_DIR}")
        return 1
else:
