    }

def round_dirs(output_dir: Path, kind: str) -> list[tuple[int, Path]]:
    """
    Sorted (round_number, path) for output_dir/<kind>/round-N directories.

`kind` is 'frames', 'critiques', or 'prompts'.
"""
base = output_dir / kind
