for _, directory in reversed(candidates):
    for ext in IMAGE_EXTS:
        candidate = directory / f"{shot_id}.{ext}"
        if candidate.exists():
            return candidate
legacy = output_dir / "generated"
if legacy.is_dir():
    for ext in IMAGE_EXTS:
        candidate = legacy / f"{shot_id}.{ext}"
        if candidate.exists():
            return candidate
return None

